// @title Gordian API
// @version 1.0
// @description Authentication and user management REST API for Gordian
// @BasePath /api/v1
// @schemes http https
// @securityDefinitions.apikey BearerAuth
// @in header
// @name Authorization
package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/mAmineChniti/Gordian/internal/config"
	"github.com/mAmineChniti/Gordian/internal/database"
	"github.com/mAmineChniti/Gordian/internal/server"

	// docs import for swag (generated by `swag init`)
	_ "github.com/mAmineChniti/Gordian/docs"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatalf("configuration error: %v", err)
	}
	for _, warning := range cfg.Warnings {
		log.Printf("warning: %s", warning)
	}

	dbService, err := database.New(cfg)
	if err != nil {
		log.Fatalf("database initialization failed: %v", err)
	}

	apiServer, err := server.NewServer(cfg, dbService)
	if err != nil {
		log.Fatalf("server initialization failed: %v", err)
	}

	cleanupCtx, stopCleanup := context.WithCancel(context.Background())
	var cleanupWG sync.WaitGroup
	cleanupWG.Add(1)
	go func() {
		defer cleanupWG.Done()
		runUnconfirmedUserCleanup(cleanupCtx, dbService)
	}()

	signalCtx, stopSignals := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stopSignals()

	shutdownDone := make(chan struct{})
	go func() {
		defer close(shutdownDone)
		<-signalCtx.Done()

		log.Println("Shutting down gracefully, press Ctrl+C again to force")
		stopCleanup()

		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if err := apiServer.Shutdown(ctx); err != nil {
			log.Printf("server forced to shut down: %v", err)
		}
	}()

	log.Printf("Starting server on %s", apiServer.Addr)
	serveErr := apiServer.ListenAndServe()
	if serveErr != nil && !errors.Is(serveErr, http.ErrServerClosed) {
		log.Printf("http server error: %v", serveErr)
	}

	stopSignals()
	<-shutdownDone
	stopCleanup()
	cleanupWG.Wait()

	closeCtx, cancelClose := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancelClose()
	if err := dbService.Close(closeCtx); err != nil {
		log.Printf("database close error: %v", err)
	}

	if serveErr != nil && !errors.Is(serveErr, http.ErrServerClosed) {
		os.Exit(1)
	}
	log.Println("Graceful shutdown complete")
}

func runUnconfirmedUserCleanup(ctx context.Context, dbService database.Service) {
	ticker := time.NewTicker(6 * time.Hour)
	defer ticker.Stop()

	if err := dbService.DeleteUnconfirmedUsers(); err != nil {
		log.Printf("initial unconfirmed users cleanup error: %v", err)
	}

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if err := dbService.DeleteUnconfirmedUsers(); err != nil {
				log.Printf("periodic unconfirmed users cleanup error: %v", err)
			}
		}
	}
}
